"""Check every number quoted in the manuscript text against the raw result CSVs (fails loudly on mismatch)."""
import sys, pandas as pd, numpy as np
from pathlib import Path
R = Path(__file__).resolve().parent / "results"; bad = []
def chk(name, got, want, tol=0.006):
    ok = abs(got - want) <= tol
    if not ok: bad.append(name)
    print(("OK  " if ok else "FAIL"), f"{name}: computed {got:.4f} vs text {want}")
cal = pd.read_csv(R/"forecast_calibration_summary.csv"); c = lambda r,h,k: float(cal[(cal.regime==r)&(cal.h==h)][k].iloc[0])
for r,h,w in [("ar",1,.046),("ar",28,.083),("drift",1,.038),("drift",28,.053),("iid",1,.034)]: chk(f"WAPE {r} h{h}", c(r,h,"wape"), w, .0006)
for h,k,w in [(1,"cov_pooled",.90),(28,"cov_pooled",.68),(1,"cov_hspec",.79),(28,"cov_hspec",.73)]: chk(f"AR coverage {k} h{h}", c("ar",h,k), w, .006)
pc = pd.read_csv(R/"paired_comparisons_main.csv"); pc = pc[pc.horizons=="h1-7-14"]; g = lambda comp,r: pc[(pc.comparison==comp)&(pc.regime==r)].iloc[0]
for r,w in [("iid",0),("ar",.08),("surge",.01),("drift",.04)]: chk(f"B {r}", g("vs_pooled(B)",r).mean_delta, w, .006)
chk("C min", min(g("vs_point(C)",r).mean_delta for r in ["iid","ar","surge","drift"]), .07, .006); chk("C max", max(g("vs_point(C)",r).mean_delta for r in ["iid","ar","surge","drift"]), .24, .006)
chk("D min", min(g("vs_buffer(D)",r).mean_delta for r in ["iid","ar","surge","drift"]), .56, .006); chk("D max", max(g("vs_buffer(D)",r).mean_delta for r in ["iid","ar","surge","drift"]), .87, .006)
for r in ["iid","ar","surge","drift"]: chk(f"E {r} exactly 0", abs(g("vs_ungated(E)",r).mean_delta), 0, 1e-12)
chk("oracle gap min", -max(g("oracle_gap",r).mean_delta for r in ["iid","ar","surge","drift"]), 1.57, .06); chk("oracle gap max", -min(g("oracle_gap",r).mean_delta for r in ["iid","ar","surge","drift"]), 3.65, .06)
chk("HCCR cut min %", min(g("vs_reactive",r).pct_of_reactive for r in ["iid","ar","surge","drift"]), 40, 0.6); chk("HCCR cut max %", max(g("vs_reactive",r).pct_of_reactive for r in ["iid","ar","surge","drift"]), 54, 0.6)
ph = pd.read_csv(R/"paired_by_horizon_main.csv"); p = lambda h: float(ph[(ph.comparison=="vs_pooled")&(ph.regime=="ar")&(ph.h==h)].mean_delta.iloc[0])
chk("AR B h1", p(1), .29); chk("AR B h14", p(14), -.12, .007); chk("AR B h28", p(28), -.42)
ct = pd.read_csv(R/"comparison_table.csv"); a = ct[ct.scope=="aggregate"].set_index("policy")
for pol,w in [("point",45),("pooled",46),("hspec",46),("buffer",43),("robust",19)]: chk(f"saving% {pol}", 100*(1-a.loc[pol].cost_total/a.loc["reactive"].cost_total), w, .6)
for pol,w in [("buffer",69.6),("oracle",60.4),("reactive",26.2),("hspec",62.1)]: chk(f"route feas {pol}", 100*a.loc[pol].route_feas, w, .06)
cap = pd.read_csv(R/"routing_capacity_vs_feasibility.csv").set_index("policy")
chk("reactive agg-ok", cap.loc["reactive"].n_agg_ok, 70, 0); chk("reactive unroutable", cap.loc["reactive"].routing_infeasible_despite_agg_ok, 7, 0)
chk("oracle agg-ok", cap.loc["oracle"].n_agg_ok, 184, 0); chk("oracle unroutable", cap.loc["oracle"].routing_infeasible_despite_agg_ok, 39, 0)
fp = pd.read_csv(R/"forecast_model_paired.csv").set_index(["regime","comparison"]).mean_delta
for k,w in [(("iid","hw-lr"),.23),(("surge","hw-lr"),.94),(("drift","hw-lr"),.10),(("ar","hw-lr"),.04)]: chk(f"HW-LR {k[0]}", fp[k], w)
nv = [fp[(r,"naive-lr")] for r in ["iid","ar","surge","drift"]]; chk("naive-LR min", min(nv), .70); chk("naive-LR max", max(nv), 1.66)
s = pd.read_csv(R/"sensitivity_summary.csv"); s = s[s.regime=="ALL"]; q = lambda pa,v,cmp: s[(s.param==pa)&(s.value==v)&(s.comparator==cmp)].iloc[0]
chk("sens saving pi=1", q("shortage_penalty",1.0,"reactive").mean_delta, 1.8, .06); chk("sens saving pi=4", q("shortage_penalty",4.0,"reactive").mean_delta, 34.35, .06)
chk("sens kappa1.2 point", q("capacity_pressure_kappa",1.2,"point").mean_delta, -.02); chk("sens kappa1.2 ungated", q("capacity_pressure_kappa",1.2,"ungated").mean_delta, -.16)
d = pd.read_csv(R/"operational_main.csv"); ug = d[(d.policy=="robust")&(d.variant=="ungated")&d.h.isin([1,7,14])].groupby(["regime","seed"]).cost_total.mean().mean()
chk("robust ungated cost", ug, 18.3, .1)

dd = pd.read_csv(R/"decision_disagreement.csv").groupby("regime").frac_different.mean()
for k,w in [("iid",.003),("drift",.028),("surge",.044),("ar",.094)]: chk(f"disagree {k}", dd[k], w, .0006)
chk("buffer-HCCR cost", a.loc["buffer"].cost_total - a.loc["hspec"].cost_total, .66, .006)
chk("n_reserved buffer", a.loc["buffer"].n_reserved, .91, .006); chk("n_reserved hspec", a.loc["hspec"].n_reserved, .66, .006)
chk("unmet buffer", a.loc["buffer"].unmet, 1.09, .006); chk("unmet hspec", a.loc["hspec"].unmet, 1.62, .006)
chk("surge B", g("vs_pooled(B)","surge").mean_delta, .01, .006)
chk("max regime disagree <0.10", float(dd.max()), 0.094, .0006)

rb = pd.read_csv(R/"replication_B.csv"); rp = lambda r,h,k: float(rb[(rb.regime==r)&(rb.horizons==h)][k].iloc[0])
for r,w in [("ar",.88),("drift",1.08)]: chk(f"replication pct {r}", rp(r,"h1-7-14","pct_of_hccr"), w, .006)
chk("replication AR h1 delta", rp("ar","h1","mean_delta"), .39, .006); chk("replication AR h28 delta", rp("ar","h28","mean_delta"), -.47, .006)
chk("replication drift CI lo", rp("drift","h1-7-14","ci_lo"), .04, .006); chk("replication drift CI hi", rp("drift","h1-7-14","ci_hi"), .32, .006)
pct = lambda r,h: float(100*ph[(ph.comparison=="vs_pooled")&(ph.regime==r)&(ph.h==h)].mean_delta.iloc[0]/ph[(ph.comparison=="vs_pooled")&(ph.regime==r)&(ph.h==h)].cost_a.iloc[0])
chk("AR h1 pct of HCCR", pct("ar",1), 2.2, .06); chk("AR h14 pct", pct("ar",14), -.8, .06); chk("AR h28 pct", pct("ar",28), -2.5, .06)
for r,w in [("ar",.53),("drift",.29),("surge",.09)]: chk(f"B pct {r}", float(100*g("vs_pooled(B)",r).mean_delta/g("vs_pooled(B)",r).cost_a), w, .006)
chk("IID B mean", g("vs_pooled(B)","iid").mean_delta, -.0003, .00006); chk("AR dz", g("vs_pooled(B)","ar").dz, 1.14, .006)
chk("robust ungated reserve cost", a.loc["robust_ungated"].cost_reserve, 17.86, .006)

# ---- priority-revision claims: coverage wording, full-sample disagreement, mechanism experiment
c = lambda r,h,k: float(cal[(cal.regime==r)&(cal.h==h)][k].iloc[0])
for h,w in [(1,.79),(14,.76),(28,.73)]: chk(f"AR hspec coverage h{h}", c("ar",h,"cov_hspec"), w, .006)
chk("AR h7 pooled cov", c("ar",7,"cov_pooled"), .788, .0006); chk("AR h7 hspec cov", c("ar",7,"cov_hspec"), .777, .0006)
chk("Drift h7 pooled cov", c("drift",7,"cov_pooled"), .805, .0006); chk("Drift h7 hspec cov", c("drift",7,"cov_hspec"), .783, .0006)
ds = pd.read_csv(R/"decision_disagreement_summary.csv"); q = lambda smp,reg,hz,k: float(ds[(ds["sample"]==smp)&(ds.decisions=="ungated")&(ds.regime==reg)&(ds.horizons==hz)][k].iloc[0])
for reg,w in [("iid",.004),("drift",.036),("surge",.038),("ar",.083)]: chk(f"disagree primary {reg}", 100*q("primary",reg,"h1-7-14","mean"), 100*w, .06)
chk("disagree AR CI lo", 100*q("primary","ar","h1-7-14","ci_lo"), 7.4, .06); chk("disagree AR CI hi", 100*q("primary","ar","h1-7-14","ci_hi"), 9.1, .06)
chk("disagree replication AR", 100*q("replication","ar","h1-7-14","mean"), 9.0, .06)
chk("disagree AR h1", 100*q("primary","ar","h1","mean"), 14.0, .06); chk("disagree AR h28", 100*q("primary","ar","h28","mean"), 17.4, .06)
chk("disagree AR h1 CI lo", 100*q("primary","ar","h1","ci_lo"), 12.6, .06); chk("disagree AR h1 CI hi", 100*q("primary","ar","h1","ci_hi"), 15.4, .06)
chk("disagree AR h28 CI lo", 100*q("primary","ar","h28","ci_lo"), 15.6, .06); chk("disagree AR h28 CI hi", 100*q("primary","ar","h28","ci_hi"), 19.4, .06)
chk("disagree max sim AR", 100*q("primary","ar","h1-7-14","max_sim"), 15.7, .06)
allmin = 100*min(q(smp,reg,"h1-7-14","mean") for smp in ("primary","replication") for reg in ("iid","ar","surge","drift")); allmax = 100*max(q(smp,reg,"h1-7-14","mean") for smp in ("primary","replication") for reg in ("iid","ar","surge","drift"))
chk("abstract disagreement min 0.4", allmin, 0.4, .06); chk("abstract disagreement max 9.0", allmax, 9.0, .06)
mp = pd.read_csv(R/"mechanism_confirm_primary.csv").set_index("contrast"); mc = pd.read_csv(R/"mechanism_confirm_cells.csv")
m = lambda phi,cond,h,k="mean",met="delta": float(mc[(mc.phi==phi)&(mc.condition==cond)&(mc.h==h)&(mc.metric==met)][k].iloc[0])
chk("Theta28", mp.loc["Theta_h28","mean"], .32, .006); chk("Theta28 lo", mp.loc["Theta_h28","ci95_lo"], .28, .006); chk("Theta28 hi", mp.loc["Theta_h28","ci95_hi"], .37, .006)
chk("Theta14", mp.loc["Theta_h14","mean"], .03, .006); chk("Theta14 lo", mp.loc["Theta_h14","ci95_lo"], .01, .006); chk("Theta14 hi", mp.loc["Theta_h14","ci95_hi"], .05, .006)
chk("Theta14 holm p", mp.loc["Theta_h14","p_holm"], .006, .0006); chk("Theta28 holm p <0.001", float(mp.loc["Theta_h28","p_holm"] < .001), 1, 0)
chk("mech n sims", mp.loc["Theta_h28","n_sims"], 60, 0)
chk("D28 natural", m(.95,"natural",28), -.445, .0006); chk("D28 anticipative", m(.95,"anticipative",28), -.112, .0006)
chk("D28 ant CI lo", m(.95,"anticipative",28,"ci_lo"), -.173, .0006); chk("D28 ant CI hi", m(.95,"anticipative",28,"ci_hi"), -.054, .0006)
chk("D1 natural", m(.95,"natural",1), .294, .0006); chk("D1 lag28", m(.95,"lag28",1), .314, .0006)
chk("W100 D28", m(.95,"W100",28), -.726, .0006); chk("W400 D28", m(.95,"W400",28), -.303, .0006); chk("finepool D28", m(.95,"finepool",28), -.466, .0006)
chk("finepool disagree h28", m(.95,"finepool",28,met="disagreement"), .748, .0006); chk("natural disagree h28", m(.95,"natural",28,met="disagreement"), .182, .0006)
chk("phi0 natural D28 ~0", abs(m(0.0,"natural",28)), .008, .0006)

# ---- relative-freshness experiment and real-data check
fp = pd.read_csv(R/"freshness_confirm_primary.csv").set_index("contrast"); fc = pd.read_csv(R/"freshness_confirm_cells.csv")
f = lambda phi,cond,h,k="mean": float(fc[(fc.phi==phi)&(fc.condition==cond)&(fc.h==h)&(fc.metric=="delta")][k].iloc[0])
chk("Psi14", fp.loc["Psi_h14","mean"], .0974, .0006); chk("Psi14 lo", fp.loc["Psi_h14","ci95_lo"], .0651, .0006); chk("Psi14 hi", fp.loc["Psi_h14","ci95_hi"], .1307, .0006)
chk("Psi28", fp.loc["Psi_h28","mean"], .0956, .0006); chk("Psi28 lo", fp.loc["Psi_h28","ci95_lo"], .0610, .0006); chk("Psi28 hi", fp.loc["Psi_h28","ci95_hi"], .1313, .0006)
chk("Psi holm <0.001", float(max(fp.p_holm) < .001), 1, 0); chk("fresh n", fp.loc["Psi_h28","n_sims"], 45, 0)
chk("D14 natural", f(.95,"natural",14), -.125, .0006); chk("D14 pooled_stale28", f(.95,"pooled_stale28",14), -.019, .0006)
chk("D28 natural fresh", f(.95,"natural",28), -.508, .0006); chk("D28 pooled_stale28", f(.95,"pooled_stale28",28), -.406, .0006)
chk("fraction of h28 reversal removed ~20%", 100*(f(.95,"pooled_stale28",28)-f(.95,"natural",28))/abs(f(.95,"natural",28)), 20, 0.6)
rdl = pd.read_csv(R/"realdata_delta.csv"); chk("real max |pct of HCCR| <0.4", float(rdl.pct_of_hccr.abs().max() < 0.4), 1, 0); chk("real max abs pct", rdl.pct_of_hccr.abs().max(), 0.325, .0006)
chk("real disagreement min", 100*rdl.disagreement.min(), 2.9, .06); chk("real disagreement max", 100*rdl.disagreement.max(), 16.5, .06); chk("real origins", rdl.n_origins.iloc[0], 103, 0)
rc_ = pd.read_csv(R/"realdata_forecast_calibration.csv").set_index("h"); chk("real cov hspec h1", rc_.loc[1,"cov_hspec"], .757, .0006); chk("real cov pooled h1", rc_.loc[1,"cov_pooled"], .762, .0006)
chk("real wape min", 100*rc_.wape.min(), 20.2, .06); chk("real wape max", 100*rc_.wape.max(), 27.2, .06)
print("\nALL CLAIMS VERIFIED" if not bad else f"\nMISMATCHES: {bad}"); sys.exit(1 if bad else 0)
